<?php
require 'inc.php';
$SC="SELECT s.Student_ID,CONCAT(s.Name,' (',c.Class_Name,'-',c.Section,')') FROM student s JOIN class c USING(Class_ID) ORDER BY c.Class_Name,c.Section,s.Name";
// Entities handled by the generic add / edit / delete / search screens: table, key, title, list SQL, search, fields, label, extra links
$E=['students'=>['student','Student_ID','Students',"SELECT s.Student_ID id,s.Admission_No `Adm No`,s.Name,CONCAT(c.Class_Name,'-',c.Section) Class,s.Contact Mobile,s.Parent_Name Parent FROM student s JOIN class c USING(Class_ID){W} ORDER BY c.Class_Name,c.Section,s.Name",'s.Name LIKE :q OR s.Admission_No LIKE :q OR s.Contact LIKE :q',['Admission_No'=>['Admission number','t'],'Name'=>['Full name','t'],'Gender'=>['Gender','g'],'DOB'=>['Date of birth','d'],'Class_ID'=>['Class','c'],'Contact'=>['Mobile','m'],'Parent_Name'=>['Parent / guardian','t'],'Parent_Contact'=>['Parent mobile','m'],'Address'=>['Address','t']],'student',[]],
'teachers'=>['teacher','Teacher_ID','Teachers',"SELECT t.Teacher_ID id,t.Name,t.Qualification,GROUP_CONCAT(b.Subject_Name SEPARATOR ', ') Subjects,t.Contact Mobile,t.Salary FROM teacher t LEFT JOIN subject b USING(Teacher_ID){W} GROUP BY t.Teacher_ID ORDER BY t.Name",'t.Name LIKE :q',['Name'=>['Full name','t'],'Qualification'=>['Qualification','t'],'Contact'=>['Mobile','m'],'Email'=>['Email','t'],'Salary'=>['Monthly salary (₹)','n']],'teacher',[]],
'subjects'=>['subject','Subject_ID','Subjects',"SELECT b.Subject_ID id,b.Subject_Name Subject,t.Name Teacher FROM subject b JOIN teacher t USING(Teacher_ID){W} ORDER BY b.Subject_Name",'b.Subject_Name LIKE :q',['Subject_Name'=>['Subject','t'],'Teacher_ID'=>['Teacher','tc']],'subject',[]],
'books'=>['book','Book_ID','Books',"SELECT b.Book_ID id,b.Book_Name Title,b.Author,b.Status,s.Name `With` FROM book b LEFT JOIN library l ON l.Book_ID=b.Book_ID AND l.Return_Date IS NULL LEFT JOIN student s ON s.Student_ID=l.Student_ID{W} ORDER BY b.Book_Name",'b.Book_Name LIKE :q OR b.Author LIKE :q',['Book_Name'=>['Title','t'],'Author'=>['Author','t']],'book',[]],
'exams'=>['examination','Exam_ID','Examinations',"SELECT Exam_ID id,Exam_Name Exam,Date,Max_Marks `Max marks` FROM examination{W} ORDER BY Date DESC",'Exam_Name LIKE :q',['Exam_Name'=>['Exam name','t'],'Date'=>['Date','d'],'Max_Marks'=>['Maximum marks','n']],'exam',['marks'=>'Enter marks','card'=>'Report card']]];
function field($c,$l,$t,$v){$i='<label'.($c=='Address'?' class="full"':'').'>'.e($l);
 if($t=='g')$i.='<select name="'.$c.'">'.opts([['Male','Male'],['Female','Female'],['Other','Other']],$v).'</select>';
 elseif($t=='c')$i.='<select name="'.$c.'">'.opts(classes(),$v).'</select>';
 elseif($t=='tc')$i.='<select name="'.$c.'">'.opts(rows("SELECT Teacher_ID,Name FROM teacher ORDER BY Name"),$v).'</select>';
 else$i.='<input name="'.$c.'" type="'.(['d'=>'date','n'=>'number','m'=>'tel'][$t]??'text').'" value="'.e($v).'" required'.($t=='m'?' pattern="[6-9][0-9]{9}" maxlength="10" title="10-digit mobile number starting with 6, 7, 8 or 9"':'').($t=='n'?' min="0" step="any"':'').'>';
 return $i.'</label>';}
function crud($k){global $E;[$t,$pk,$title,$sql,$srch,$f,$one,$links]=$E[$k];$id=(int)($_GET['id']??0);$a=$_GET['a']??'list';$errs=[];
 if(post()){
  if(isset($_POST['del'])){try{q("DELETE FROM $t WHERE $pk=?",[(int)$_POST['del']]);flash(ucfirst($one).' removed.');}catch(PDOException $x){flash("This $one is linked to other records (attendance, fees, marks or books), so it can't be deleted.",1);}go("index.php?p=$k");}
  $v=[];foreach($f as $c=>[$l,$ty]){$v[$c]=trim($_POST[$c]??'');
   if($v[$c]==='')$errs[]="$l is required.";elseif($ty=='m'&&!preg_match('/^[6-9]\d{9}$/',$v[$c]))$errs[]="$l must be a 10-digit Indian mobile number.";elseif($ty=='n'&&(!is_numeric($v[$c])||$v[$c]<0))$errs[]="$l must be a positive number.";elseif($ty=='d'&&!strtotime($v[$c]))$errs[]="$l is not a valid date.";}
  if(!$errs){$cols=array_keys($f);try{
    if($id)q("UPDATE $t SET ".implode(',',array_map(fn($c)=>"$c=?",$cols))." WHERE $pk=?",[...array_values($v),$id]);
    else q("INSERT INTO $t(".implode(',',$cols).") VALUES(".implode(',',array_fill(0,count($cols),'?')).")",array_values($v));
    flash(ucfirst($one).' saved.');go("index.php?p=$k");}catch(PDOException $x){$errs[]=$x->getCode()==23000?'That entry already exists, or it points to something that is missing.':'Could not save. Please check the details.';}}
  $old=$v;$a=$id?'edit':'add';}
 if($a=='add'||$a=='edit'){$old??=$id?row("SELECT * FROM $t WHERE $pk=?",[$id]):[];head(($id?'Edit ':'Add ').$one);foreach($errs as $m)echo '<div class="msg bad">'.e($m).'</div>';
  echo '<form method="post" class="card grid">'.csrf();foreach($f as $c=>[$l,$ty])echo field($c,$l,$ty,$old[$c]??'');
  echo '<div class="full"><button class="btn">Save '.$one.'</button> <a class="btn ghost" href="index.php?p='.$k.'">Cancel</a></div></form>';foot();return;}
 head($title);$s=trim($_GET['s']??'');
 echo '<form class="bar noprint"><input type="hidden" name="p" value="'.$k.'"><label>Search<input name="s" value="'.e($s).'" placeholder="Type and press Enter"></label><span class="sp"></span>';
 foreach($links as $lp=>$ll)echo '<a class="btn ghost" href="index.php?p='.$lp.'">'.$ll.'</a>';echo '<a class="btn" href="index.php?p='.$k.'&a=add">Add '.$one.'</a></form>';
 tbl(rows(str_replace('{W}',$s!==''?" WHERE $srch":'',$sql),$s!==''?['q'=>"%$s%"]:[]),fn($x)=>'<a href="index.php?p='.$k.'&a=edit&id='.$x['id'].'">Edit</a><form method="post" data-confirm="Remove this '.$one.'? This cannot be undone.">'.csrf().'<input type="hidden" name="del" value="'.$x['id'].'"><button class="lnk bad">Delete</button></form>',"No $one matches that search.");foot();}
function login(){$err='';if(post()){$u=row("SELECT * FROM admin WHERE Username=? AND Status='Active'",[trim($_POST['u'])]);
  if($u&&password_verify($_POST['p'],$u['Password'])){session_regenerate_id(true);$_SESSION['u']=$u;$_SESSION['t']=time();go('index.php');}$err='That username or password is not right. Please try again.';}
 echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in | '.SCHOOL.'</title><link rel="stylesheet" href="style.css"></head><body><div class="login"><div class="l"><svg width="46" height="46" viewBox="0 0 46 46"><rect x="2" y="2" width="42" height="42" rx="8" fill="none" stroke="#E8A317" stroke-width="3"/><path d="M12 32V16l11 7 11-7v16" fill="none" stroke="#fff" stroke-width="3"/></svg><h1>'.SCHOOL.'</h1><p>Attendance, marks, fees and the library, all kept in one tidy place for the school office.</p><small style="opacity:.7">DBMS project · BBA (Computer Applications) · G H Raisoni Skill Tech University<br>Atharva Ingale and Indrayani Mazumder</small></div><div class="r"><form method="post"><h2 style="margin-bottom:6px">Sign in</h2><p class="muted" style="margin-top:0">Use the username given by the school office.</p>'.($err?'<div class="msg bad">'.$err.'</div>':'').csrf().'<label>Username<input name="u" required autofocus></label><br><label>Password<input name="p" type="password" required></label><br><button class="btn" style="width:100%">Sign in</button></form></div></div></body></html>';exit;}
function dash(){head('Dashboard');$h=date('G');$n=explode(' ',preg_replace('/^(Mr|Mrs|Dr|Ms)\.\s*/','',me()['Full_Name']))[0];
 echo '<p class="hi">'.($h<12?'Good morning':($h<17?'Good afternoon':'Good evening')).', '.e($n).'.</p><div class="stats">';
 $tp=one("SELECT ROUND(AVG(Status<>'Absent')*100) FROM attendance WHERE Date=CURDATE()");
 foreach([['Students',one('SELECT COUNT(*) FROM student')],['Teachers',one('SELECT COUNT(*) FROM teacher')],['Attendance today',$tp===null?'Not marked':$tp.'%'],['Fees collected this month',inr(one("SELECT COALESCE(SUM(Amount),0) FROM fees WHERE Status='Paid' AND DATE_FORMAT(Payment_Date,'%Y-%m')=DATE_FORMAT(CURDATE(),'%Y-%m')"))],['Fees pending',inr(one("SELECT COALESCE(SUM(Amount),0) FROM fees WHERE Status='Pending'"))],['Books issued',one("SELECT COUNT(*) FROM library WHERE Return_Date IS NULL")]] as [$l,$v])echo '<div class="stat"><b>'.$v.'</b><span>'.$l.'</span></div>';
 echo '</div><div class="cols"><div class="card"><h2>Attendance not yet marked today</h2>';tbl(rows("SELECT CONCAT(Class_Name,'-',Section) Class FROM class WHERE Class_ID NOT IN (SELECT s.Class_ID FROM attendance a JOIN student s USING(Student_ID) WHERE a.Date=CURDATE())"),null,'Every class has been marked for today.');
 echo '</div><div class="card"><h2>Recent fee payments</h2>';tbl(rows("SELECT s.Name Student,f.Amount,f.Payment_Date `Paid on` FROM fees f JOIN student s USING(Student_ID) WHERE f.Status='Paid' ORDER BY f.Payment_Date DESC,f.Fee_ID DESC LIMIT 5"));
 echo '</div><div class="card"><h2>Overdue library books</h2>';tbl(rows("SELECT b.Book_Name Title,s.Name Student,l.Due_Date `Due on` FROM library l JOIN book b USING(Book_ID) JOIN student s USING(Student_ID) WHERE l.Return_Date IS NULL AND l.Due_Date<CURDATE()"),null,'No books are overdue. Everything is on time.');echo '</div></div>';foot();}
function att(){global $SC;$c=(int)($_GET['c']??0);$d=$_GET['d']??date('Y-m-d');$m=$_GET['m']??date('Y-m');
 if(post()){$S=$_POST['s']??[];foreach($S as $sid=>$st)if(in_array($st,['Present','Absent','Late']))q("INSERT INTO attendance(Student_ID,Date,Status) VALUES(?,?,?) ON DUPLICATE KEY UPDATE Status=VALUES(Status)",[(int)$sid,$_POST['d'],$st]);
  flash('Attendance saved. '.count(array_filter($S,fn($x)=>$x=='Absent')).' marked absent.');go('index.php?p=attendance&c='.(int)$_POST['cc'].'&d='.$_POST['d']);}
 head('Attendance');echo '<form class="bar card noprint"><input type="hidden" name="p" value="attendance"><label>Class<select name="c">'.opts(classes(),$c).'</select></label><label>Date<input type="date" name="d" value="'.e($d).'" max="'.date('Y-m-d').'"></label><label>Month summary<input type="month" name="m" value="'.e($m).'"></label><button class="btn">Show</button></form>';
 $st=rows("SELECT s.Student_ID id,s.Name,a.Status FROM student s LEFT JOIN attendance a ON a.Student_ID=s.Student_ID AND a.Date=? WHERE s.Class_ID=? ORDER BY s.Name",[$d,$c?:1]);
 echo '<form method="post" class="card"><h2>Daily register, '.dmy($d).'</h2>'.csrf().'<input type="hidden" name="d" value="'.e($d).'"><input type="hidden" name="cc" value="'.($c?:1).'">';
 foreach($st as $x){echo '<div class="radios" style="padding:6px 0;border-bottom:1px solid var(--border)"><b style="display:inline-block;width:210px">'.e($x['Name']).'</b>';foreach(['Present','Absent','Late'] as $o)echo '<label><input type="radio" name="s['.$x['id'].']" value="'.$o.'"'.(($x['Status']?:'Present')==$o?' checked':'').'>'.$o.'</label>';echo '</div>';}
 echo '<p><button class="btn">Save attendance</button></p></form><h2 style="margin:8px 0 12px">Monthly attendance, '.date('F Y',strtotime($m.'-01')).'</h2>';
 tbl(rows("SELECT s.Name,SUM(a.Status<>'Absent') `Days present`,COUNT(*) `Days marked`,ROUND(SUM(a.Status<>'Absent')/COUNT(*)*100) `Attendance %` FROM attendance a JOIN student s USING(Student_ID) WHERE s.Class_ID=? AND DATE_FORMAT(a.Date,'%Y-%m')=? GROUP BY s.Student_ID ORDER BY s.Name",[$c?:1,$m]),null,'No attendance was marked for this class in that month.');foot();}
function marks(){global $SC;$e=(int)($_GET['e']??0);$c=(int)($_GET['c']??0);$b=(int)($_GET['b']??0);
 if(post()){$mx=one("SELECT Max_Marks FROM examination WHERE Exam_ID=?",[$_POST['e']]);$bad=0;foreach($_POST['m'] as $sid=>$v){if($v===''||!is_numeric($v)||$v<0||$v>$mx){$bad++;continue;}q("INSERT INTO result(Student_ID,Exam_ID,Subject_ID,Marks,Grade) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE Marks=VALUES(Marks),Grade=VALUES(Grade)",[(int)$sid,$_POST['e'],$_POST['b'],$v,grade($v,$mx)]);}
  flash($bad?"Saved. $bad row(s) skipped because the marks were empty or above $mx.":'Marks saved and grades worked out.',(bool)$bad);go("index.php?p=marks&e={$_POST['e']}&c={$_POST['c']}&b={$_POST['b']}");}
 head('Enter marks');echo '<form class="bar card"><input type="hidden" name="p" value="marks"><label>Exam<select name="e">'.opts(rows("SELECT Exam_ID,Exam_Name FROM examination ORDER BY Date DESC"),$e).'</select></label><label>Class<select name="c">'.opts(classes(),$c).'</select></label><label>Subject<select name="b">'.opts(rows("SELECT Subject_ID,Subject_Name FROM subject ORDER BY Subject_Name"),$b).'</select></label><button class="btn">Load students</button></form>';
 if($e&&$c&&$b){$mx=one("SELECT Max_Marks FROM examination WHERE Exam_ID=?",[$e]);echo '<form method="post" class="card"><h2>Marks out of '.$mx.'</h2>'.csrf().'<input type="hidden" name="e" value="'.$e.'"><input type="hidden" name="c" value="'.$c.'"><input type="hidden" name="b" value="'.$b.'">';
  foreach(rows("SELECT s.Student_ID,s.Name,r.Marks FROM student s LEFT JOIN result r ON r.Student_ID=s.Student_ID AND r.Exam_ID=? AND r.Subject_ID=? WHERE s.Class_ID=? ORDER BY s.Name",[$e,$b,$c]) as $x)echo '<div style="display:flex;align-items:center;gap:14px;padding:5px 0"><b style="width:220px">'.e($x['Name']).'</b><input style="width:100px;margin:0" type="number" step="0.5" min="0" max="'.$mx.'" name="m['.$x['Student_ID'].']" value="'.e($x['Marks']).'"></div>';
  echo '<p><button class="btn">Save marks</button></p></form>';}foot();}
function card(){global $SC;$sid=(int)($_GET['sid']??0);$e=(int)($_GET['e']??0);head('Report card');
 echo '<form class="bar card noprint"><input type="hidden" name="p" value="card"><label>Student<select name="sid">'.opts(rows($SC),$sid).'</select></label><label>Exam<select name="e">'.opts(rows("SELECT Exam_ID,Exam_Name FROM examination ORDER BY Date DESC"),$e).'</select></label><button class="btn">Show report card</button></form>';
 if($sid&&$e){$s=row("SELECT s.*,CONCAT(c.Class_Name,'-',c.Section) Cl FROM student s JOIN class c USING(Class_ID) WHERE Student_ID=?",[$sid]);$x=row("SELECT * FROM examination WHERE Exam_ID=?",[$e]);
  $r=rows("SELECT b.Subject_Name Subject,r.Marks,? `Out of`,r.Grade FROM result r JOIN subject b USING(Subject_ID) WHERE r.Student_ID=? AND r.Exam_ID=? ORDER BY b.Subject_Name",[$x['Max_Marks'],$sid,$e]);
  echo '<div class="rc"><h2>'.SCHOOL.'</h2><p class="c">'.CITY.' · Academic year '.YEAR.'<br><b>Report card, '.e($x['Exam_Name']).'</b></p><p><b>'.e($s['Name']).'</b> · Class '.$s['Cl'].' · Admission no. '.e($s['Admission_No']).'<br>Parent: '.e($s['Parent_Name']).'</p>';
  if(!$r)echo '<p class="muted">Marks for this exam have not been entered yet.</p>';else{$tot=array_sum(array_column($r,'Marks'));$mxs=count($r)*$x['Max_Marks'];$pc=round($tot/$mxs*100,1);$fail=in_array('F',array_column($r,'Grade'));
   tbl($r);$at=one("SELECT ROUND(SUM(Status<>'Absent')/COUNT(*)*100) FROM attendance WHERE Student_ID=?",[$sid]);
   echo '<p>Total <b>'.$tot.' / '.$mxs.'</b> · Percentage <b>'.$pc.'%</b> · Overall grade <b>'.grade($tot,$mxs).'</b> · Result '.cell('',$fail?'Fail':'Pass').'<br>Attendance this term: <b>'.($at??'—').'%</b></p>';}
  echo '</div><p class="noprint"><button class="btn" onclick="print()">Print report card</button></p>';}foot();}
function fees(){$s=trim($_GET['s']??'');$st=$_GET['st']??'';$w=['1'];$a=[];if($s!==''){$w[]='(s.Name LIKE :q OR f.Receipt_No LIKE :q)';$a['q']="%$s%";}if(in_array($st,['Paid','Pending'])){$w[]='f.Status=:st';$a['st']=$st;}
 head('Fees');$tot=row("SELECT SUM(Status='Pending')*0+COALESCE(SUM(CASE WHEN Status='Pending' THEN Amount END),0) d,COALESCE(SUM(CASE WHEN Status='Paid' THEN Amount END),0) c FROM fees");
 echo '<div class="stats"><div class="stat"><b>'.inr($tot['c']).'</b><span>Collected so far</span></div><div class="stat"><b>'.inr($tot['d']).'</b><span>Still due</span></div></div><form class="bar noprint"><input type="hidden" name="p" value="fees"><label>Search<input name="s" value="'.e($s).'" placeholder="Student or receipt number"></label><label>Status<select name="st"><option value="">All</option><option'.($st=='Pending'?' selected':'').'>Pending</option><option'.($st=='Paid'?' selected':'').'>Paid</option></select></label><button class="btn">Filter</button></form>';
 tbl(rows("SELECT f.Fee_ID id,s.Name Student,f.Fee_Type `Fee`,f.Amount,f.Due_Date `Due on`,IF(f.Status='Pending' AND f.Due_Date<CURDATE(),'Overdue',f.Status) Status,f.Payment_Date `Paid on`,f.Payment_Mode Mode,f.Receipt_No Receipt FROM fees f JOIN student s USING(Student_ID) WHERE ".implode(' AND ',$w)." ORDER BY f.Status DESC,f.Due_Date,s.Name LIMIT 200",$a),fn($x)=>$x['Status']=='Paid'?'<a href="index.php?p=receipt&id='.$x['id'].'">Receipt</a>':'<a href="index.php?p=pay&id='.$x['id'].'">Collect</a>','No fee records match.');foot();}
function pay(){$id=(int)$_GET['id'];$f=row("SELECT f.*,s.Name FROM fees f JOIN student s USING(Student_ID) WHERE Fee_ID=? AND Status='Pending'",[$id]);if(!$f){flash('That instalment is already paid or does not exist.',1);go('index.php?p=fees');}
 if(post()&&in_array($_POST['m'],['Cash','UPI','Cheque','Card'])){q("UPDATE fees SET Status='Paid',Payment_Date=CURDATE(),Payment_Mode=?,Receipt_No=? WHERE Fee_ID=?",[$_POST['m'],'VEMS/'.date('y').'/'.str_pad($id,4,'0',STR_PAD_LEFT),$id]);flash('Payment recorded. The receipt is ready.');go("index.php?p=receipt&id=$id");}
 head('Collect fee');echo '<form method="post" class="card grid">'.csrf().'<p class="full"><b>'.e($f['Name']).'</b><br>'.e($f['Fee_Type']).' · '.inr($f['Amount']).' · due '.dmy($f['Due_Date']).'</p><label>Payment mode<select name="m"><option>Cash</option><option>UPI</option><option>Cheque</option><option>Card</option></select></label><div class="full"><button class="btn">Record payment of '.inr($f['Amount']).'</button> <a class="btn ghost" href="index.php?p=fees">Cancel</a></div></form>';foot();}
function receipt(){$f=row("SELECT f.*,s.Name,s.Admission_No,CONCAT(c.Class_Name,'-',c.Section) Cl FROM fees f JOIN student s USING(Student_ID) JOIN class c USING(Class_ID) WHERE Fee_ID=? AND Status='Paid'",[(int)$_GET['id']]);head('Fee receipt');if(!$f){echo '<p>Receipt not found.</p>';foot();return;}
 echo '<div class="rc"><h2>'.SCHOOL.'</h2><p class="c">'.CITY.'<br><b>Fee receipt</b></p><p>Receipt no. <b>'.e($f['Receipt_No']).'</b> · Date '.dmy($f['Payment_Date']).'<br>Received from <b>'.e($f['Name']).'</b>, Class '.$f['Cl'].' (Adm. no. '.e($f['Admission_No']).')<br>Towards '.e($f['Fee_Type']).' · Paid by '.e($f['Payment_Mode']).'</p><p style="font:600 24px var(--serif)">'.inr($f['Amount']).'</p><p>'.words((int)$f['Amount']).'</p></div><p class="noprint"><button class="btn" onclick="print()">Print receipt</button></p>';foot();}
function lib(){global $SC;
 if(post()){if(isset($_POST['ret'])){$l=row("SELECT * FROM library WHERE Issue_ID=? AND Return_Date IS NULL",[$_POST['ret']]);if($l){$late=max(0,(int)((time()-strtotime($l['Due_Date']))/86400));$fine=$late*FINE;q("UPDATE library SET Return_Date=CURDATE(),Fine_Amount=? WHERE Issue_ID=?",[$fine,$l['Issue_ID']]);q("UPDATE book SET Status='Available' WHERE Book_ID=?",[$l['Book_ID']]);flash($fine?"Book returned. It was $late day(s) late, so the fine is ".inr($fine).'.':'Book returned on time. No fine.');}}
  elseif(one("SELECT Status FROM book WHERE Book_ID=?",[$_POST['b']])=='Available'){q("INSERT INTO library(Book_ID,Student_ID,Issue_Date,Due_Date) VALUES(?,?,CURDATE(),DATE_ADD(CURDATE(),INTERVAL ".LOAN." DAY))",[$_POST['b'],$_POST['s']]);q("UPDATE book SET Status='Issued' WHERE Book_ID=?",[$_POST['b']]);flash('Book issued. It is due back in '.LOAN.' days.');}else flash('That book is already out with someone else.',1);go('index.php?p=library');}
 head('Library');echo '<form method="post" class="bar card">'.csrf().'<label>Book<select name="b">'.opts(rows("SELECT Book_ID,Book_Name FROM book WHERE Status='Available' ORDER BY Book_Name")).'</select></label><label>Student<select name="s">'.opts(rows($SC)).'</select></label><button class="btn">Issue book</button></form><h2 style="margin-bottom:12px">Books currently out</h2>';
 tbl(rows("SELECT l.Issue_ID id,b.Book_Name Title,s.Name Student,l.Issue_Date `Issued on`,l.Due_Date `Due on`,IF(l.Due_Date<CURDATE(),'Overdue','Issued') Status,IF(l.Due_Date<CURDATE(),DATEDIFF(CURDATE(),l.Due_Date)*".FINE.",0) Fine FROM library l JOIN book b USING(Book_ID) JOIN student s USING(Student_ID) WHERE l.Return_Date IS NULL ORDER BY l.Due_Date"),fn($x)=>'<form method="post">'.csrf().'<input type="hidden" name="ret" value="'.$x['id'].'"><button class="lnk">Mark returned</button></form>','No books are out right now. Everything is back on the shelf.');foot();}
function reps(){head('Reports');echo '<p class="noprint"><button class="btn" onclick="print()">Print these reports</button></p><div class="cols">';
 foreach(['Fee defaulters (overdue)'=>"SELECT s.Name,CONCAT(c.Class_Name,'-',c.Section) Class,SUM(f.Amount) Due FROM fees f JOIN student s USING(Student_ID) JOIN class c USING(Class_ID) WHERE f.Status='Pending' AND f.Due_Date<CURDATE() GROUP BY s.Student_ID ORDER BY Due DESC,s.Name LIMIT 15",
 'Attendance below 75%'=>"SELECT s.Name,CONCAT(c.Class_Name,'-',c.Section) Class,ROUND(SUM(a.Status<>'Absent')/COUNT(*)*100) `Attendance %` FROM attendance a JOIN student s USING(Student_ID) JOIN class c USING(Class_ID) GROUP BY s.Student_ID HAVING `Attendance %`<75 ORDER BY `Attendance %`",
 'Toppers, latest exam'=>"SELECT s.Name,CONCAT(c.Class_Name,'-',c.Section) Class,ROUND(SUM(r.Marks)/SUM(e.Max_Marks)*100,1) `Percentage` FROM result r JOIN student s USING(Student_ID) JOIN examination e USING(Exam_ID) JOIN class c USING(Class_ID) WHERE r.Exam_ID=(SELECT MAX(Exam_ID) FROM result) GROUP BY s.Student_ID ORDER BY `Percentage` DESC LIMIT 10",
 'Overdue library books'=>"SELECT b.Book_Name Title,s.Name Student,DATEDIFF(CURDATE(),l.Due_Date)*".FINE." Fine FROM library l JOIN book b USING(Book_ID) JOIN student s USING(Student_ID) WHERE l.Return_Date IS NULL AND l.Due_Date<CURDATE()"] as $t=>$s){echo '<div class="card"><h2>'.$t.'</h2>';tbl(rows($s),null,'Nothing to report. All good here.');echo '</div>';}echo '</div>';foot();}
function adm(){if(post()){if(isset($_POST['tg']))q("UPDATE admin SET Status=IF(Status='Active','Inactive','Active') WHERE Admin_ID=? AND Admin_ID<>?",[$_POST['tg'],me()['Admin_ID']]);
  elseif(isset($_POST['rp'])&&strlen($_POST['np'])>=6)q("UPDATE admin SET Password=? WHERE Admin_ID=?",[password_hash($_POST['np'],PASSWORD_DEFAULT),$_POST['rp']]);
  elseif(isset($_POST['opt'])){foreach(db()->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN) as $t)db()->query("OPTIMIZE TABLE `$t`")->fetchAll();}
  elseif(isset($_POST['un'])){if(strlen($_POST['pw'])<6||!in_array($_POST['r'],['Admin','Teacher','Accountant','Librarian'])||trim($_POST['un'])===''||trim($_POST['fn'])===''){flash('Please fill every field. The password needs at least 6 characters.',1);go('index.php?p=admin');}
   try{q("INSERT INTO admin(Username,Password,Full_Name,Role) VALUES(?,?,?,?)",[trim($_POST['un']),password_hash($_POST['pw'],PASSWORD_DEFAULT),trim($_POST['fn']),$_POST['r']]);}catch(PDOException $x){flash('That username is already taken.',1);go('index.php?p=admin');}}
  flash('Done. The change has been saved.');go('index.php?p=admin');}
 head('Admin');echo '<div class="cols"><form method="post" class="card grid"><h2 class="full">Add a user</h2>'.csrf().'<label>Full name<input name="fn" required></label><label>Username<input name="un" required></label><label>Role<select name="r"><option>Teacher</option><option>Accountant</option><option>Librarian</option><option>Admin</option></select></label><label>Password<input name="pw" type="password" minlength="6" required></label><div class="full"><button class="btn">Add user</button></div></form>
 <div class="card"><h2>Database</h2><p class="muted">Download a full copy of every table. To restore it, import the file in phpMyAdmin.</p><a class="btn" href="index.php?p=backup">Download backup</a> <form method="post" style="display:inline">'.csrf().'<button class="btn ghost" name="opt" value="1">Optimize tables</button></form></div></div><h2 style="margin-bottom:12px">Users</h2>';
 tbl(rows("SELECT Admin_ID id,Full_Name Name,Username,Role,Status FROM admin ORDER BY Role,Full_Name"),fn($x)=>'<form method="post" style="display:inline">'.csrf().'<input type="hidden" name="tg" value="'.$x['id'].'"><button class="lnk">'.($x['Status']=='Active'?'Deactivate':'Activate').'</button></form><form method="post">'.csrf().'<input type="hidden" name="rp" value="'.$x['id'].'"><input name="np" type="password" placeholder="New password" minlength="6" style="width:130px;display:inline;padding:4px 8px"> <button class="lnk">Reset</button></form>');
 echo '<h2 style="margin:22px 0 12px">Rows in each table</h2>';$r=[];foreach(db()->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN) as $t)$r[]=['Table'=>$t,'Rows'=>one("SELECT COUNT(*) FROM `$t`")];tbl($r);foot();}
$p=$_GET['p']??'dashboard';
if($p=='logout'){session_destroy();go('index.php?p=login');}
if($p=='login')login();
$gate=['marks'=>'exams','card'=>'exams','pay'=>'fees','receipt'=>'fees','backup'=>'admin'];$g=$gate[$p]??$p;need($NAV[$g][1]??null);
if($p=='backup'){header('Content-Type: application/sql');header('Content-Disposition: attachment; filename="school_backup_'.date('Ymd_His').'.sql"');echo "SET FOREIGN_KEY_CHECKS=0;\n";
 foreach(db()->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN) as $t){echo "DROP TABLE IF EXISTS `$t`;\n".row("SHOW CREATE TABLE `$t`")['Create Table'].";\n";foreach(rows("SELECT * FROM `$t`") as $r)echo "INSERT INTO `$t` VALUES(".implode(',',array_map(fn($v)=>$v===null?'NULL':db()->quote($v),$r)).");\n";}echo "SET FOREIGN_KEY_CHECKS=1;\n";exit;}
$map=['dashboard'=>'dash','attendance'=>'att','marks'=>'marks','card'=>'card','fees'=>'fees','pay'=>'pay','receipt'=>'receipt','library'=>'lib','reports'=>'reps','admin'=>'adm'];
if(isset($E[$p]))crud($p);elseif(isset($map[$p]))$map[$p]();else{head('Page not found');echo '<div class="card"><h2>We could not find that page.</h2><a href="index.php">Back to the dashboard</a></div>';foot();}
